llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Ethinylestradiol, which shares the phenolic 3-OH and steroid scaffold but has a tertiary 17-OH, shows absolute oral bioavailability of 62 ± 4.4% in humans, demonstrating that blocking 17-oxidation can overcome the low oral bioavailability typical of estradiol.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Moxestrol, a 17-modified ethinylestradiol analog with a phenolic 3-OH, has absolute oral bioavailability of 35% in humans, further supporting that 17-protected estradiol analogs can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Estetrol, a polyhydroxylated estrogen, is reported to have high and dose-related oral bioavailability in humans, indicating that multiple hydroxyl groups do not necessarily cause low F when metabolic inactivation is limited.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Estradiol itself has absolute oral bioavailability of approximately 5% in humans, which would argue for low F; however, this is largely due to rapid 17β-HSD oxidation and conjugation, a liability that is absent in the query's D-homo tertiary 17-OH.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a D-homoestradiol with a tertiary 17-OH, which should block 17β-HSD oxidation—the major first-pass inactivation pathway of estradiol. Ethinylestradiol and moxestrol, which share this protective 17-modification and phenolic 3-OH, show human oral bioavailability of 35-62%, supporting F ≥ 20%. The low F of estradiol is less transferable because its secondary 17-OH is the key liability absent in the query.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for D-homoestradiol.",
    "Uncertainty remains about intestinal/hepatic conjugation of the 3-phenol and any D-homo-specific metabolic pathways."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

